.back { margin-bottom: 20px; }
.task-row { display: flex; gap: 12px; align-items: center; padding: 12px 16px; margin: 10px 0; background: white; border: 1px solid #e0e5ec; border-radius: 8px; }
.task-row input { flex: none; }

app.innerHTML = `<button class="back" type="button">Projects</button><h1>${escapeHtml(project.name)}</h1>
  <form id="task-form"><label for="task-title">Task title</label><input id="task-title" name="title" type="text" autocomplete="off"><button type="submit">Create task</button></form>
  <div id="message"></div><label for="task-filter">Task filter</label>
  <select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
  <section id="tasks" aria-label="Tasks"></section>`;
document.querySelector('.back').addEventListener('click', () => { location.href = '/'; });
const form = document.querySelector('#task-form');
form.addEventListener('submit', async (event) => {
  event.preventDefault();
  const title = new FormData(form).get('title').trim();
  if (!title) {
    document.querySelector('#message').innerHTML = '<p role="alert">Task title is required</p>';
    return;
  }
  const created = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
  if (created.ok) { form.reset(); document.querySelector('#message').replaceChildren(); await renderTasks(id); }
});
document.querySelector('#task-filter').addEventListener('change', () => renderTasks(id));
await renderTasks(id);

async function renderTasks(projectId) {
  const response = await fetch(`/api/projects/${encodeURIComponent(projectId)}/tasks`);
  if (!response.ok) return;
  const tasks = await response.json();
  const filter = document.querySelector('#task-filter').value;
  const visible = tasks.filter(task => filter === 'All' || (filter === 'Open' && !task.completed) || (filter === 'Completed' && task.completed));
  document.querySelector('#tasks').innerHTML = visible.map(task =>
    `<div class="task-row" data-testid="task-row"><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" data-task-id="${task.id}" ${task.completed ? 'checked' : ''}><span>${escapeHtml(task.title)}</span></div>`
  ).join('');
  document.querySelectorAll('[data-task-id]').forEach(checkbox => checkbox.addEventListener('change', async () => {
    const result = await fetch(`/api/projects/${encodeURIComponent(projectId)}/tasks/${checkbox.dataset.taskId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
    if (result.ok) await renderTasks(projectId);
  }));
}

const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);

